<template>
  <q-card style="min-width: 45vw">
    <q-toolbar class="secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold text-white">{{
          mode == 'edit'
            ? $t('edit_master_data_config')
            : $t('create_master_data_config')
        }}</span>
      </q-toolbar-title>

      <q-btn flat round dense v-close-popup text-color="white" icon="close" />
    </q-toolbar>
    <q-card-section>
      <div class="row">
        <div class="col-sm-6 col-md-6 col-lg-6">
          <q-input
            outlined
            dense
            readonly
            v-model="configuration_data.doc_type"
            :label="$t('document_type')"
            class="q-mr-sm"
          />
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6">
          <q-input
            outlined
            dense
            :readonly="isReadonly"
            v-model="configuration_data.lookup_name"
            :label="$t('lookup_name')"
            :rules="[
              (val: any) =>
                !val.includes(' ') ||
                $t('no_spaces_error'),
            ]"
          />
        </div>
      </div>
      <div class="row q-pb-md">
        <div class="col-sm-6 col-md-6 col-lg-6">
          <q-select
            v-model="configuration_data.lookup_dataset_name"
            :options="filtered_master_data_types"
            :readonly="isReadonly"
            outlined
            @filter="filterDatasetNames"
            use-input
            :label="$t('lookup_dataset_name')"
            dense
            clearable
            emit-value
            map-options
            class="q-mr-sm"
          >
            <template v-slot:option="scope">
              <q-item v-bind="scope.itemProps">
                <q-item-section>
                  <q-item-label class="text-capitalize">{{
                    scope.opt.label
                  }}</q-item-label>
                </q-item-section>
              </q-item>
            </template>
            <template v-slot:selected-item="scope">
              <q-item-section>
                <q-item-label class="ellipsis text-capitalize">{{
                  scope.opt.label
                }}</q-item-label>
              </q-item-section>
            </template>
          </q-select>
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6">
          <q-select
            v-model="configuration_data.conflict_handle"
            :options="conflict_handle_options"
            :readonly="isReadonly"
            outlined
            :label="$t('conflict_handle')"
            dense
            emit-value
            map-options
          />
        </div>
      </div>
      <div class="row">
        <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
          <q-select
            v-model="configuration_data.context_type"
            :options="context_type_options"
            :readonly="isReadonly"
            outlined
            :label="$t('context_type')"
            dense
            emit-value
            map-options
            class="q-mr-sm"
          />
        </div>

        <div
          class="col-sm-6 col-md-6 col-lg-6 q-pb-md"
          v-if="configuration_data.context_type == 'line'"
        >
          <q-select
            v-model="configuration_data.context_detail"
            :options="tables_list"
            :readonly="isReadonly"
            outlined
            :label="$t('context_detail')"
            dense
            emit-value
            map-options
          />
        </div>

        <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
          <f-toggle size="xs"
            :disable="isReadonly"
            v-model="configuration_data.match_all"
            :label="$t('lbl_match_all')"
          />
        </div>
      </div>
    </q-card-section>
    <q-card-actions align="right">
      <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
      <f-btn
        v-if="!isReadonly"
        :label="mode == 'edit' ? $t('save') : $t('create')"
        @click="save"
        class="q-mr-sm"
      />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import { conflict_handle_options } from 'src/constants';
import {
  useDocTypeFieldsStore,
  useMasterDataDropdownStore,
  useDocumentStore,
} from 'src/store/main';

export default defineComponent({
    props: {
    configuration_id: {
      type: String,
      required: false,
    },
    mode: {
      type: String,
      default: 'add',
    },
  },
  async mounted() {
    this.isReadonly = this.mode == 'view' ? true : false;
    this.configuration_data.doc_type = this.$route.params.type.toString();
    if (this.mode == 'edit' || this.isReadonly) {
      this.getConfiguration(this.configuration_id);
    }
    await this.getMasterDataTypesAndFields();
    this.filtered_master_data_types = this.master_data_types;
  },
  methods: {
    filterDatasetNames(val, update, abort) {
      update(() => {
        const needle = val.toLowerCase();
        this.filtered_master_data_types = this.master_data_types.filter(
           
          (v) => v.label.toLowerCase().startsWith(needle),
        );
      });
    },

    getConfiguration(configuration_id) {
      this.lookup_configurations.find((config) => {
        if (config.id == configuration_id) {
          this.configuration_data.lookup_name = config.lookup_name;
          this.configuration_data.conflict_handle = config.conflict_handle;
          this.configuration_data.lookup_dataset_name =
            config.lookup_dataset_name || '';
          this.configuration_data.match_all = config.match_all
            ? config.match_all
            : false;
          this.configuration_data.context_type = config.context;
          this.configuration_data.context_detail = config.context_detail;
        }
      });
    },

    validInputs() {
      if (this.configuration_data.lookup_name.includes(' ')) {
        notify.error(i18n.t('no_spaces_error'));
        return false;
      }

      if (!this.configuration_data.lookup_dataset_name || '') {
        notify.error(i18n.t('fill_all_fields'));
        return false;
      }

      if (this.configuration_data.lookup_name == '') {
        notify.error(i18n.t('fill_all_fields'));
        return false;
      }

      if (this.configuration_data.context_type == 'line') {
        if (!this.configuration_data.context_detail) {
          notify.error(i18n.t('fill_all_fields'));
          return false;
        }
      } else {
        this.configuration_data.context_detail = '';
      }

      return true;
    },

    async save() {
      const valid = this.validInputs();
      if (!valid || this.isReadonly) {
        return;
      }

      try {
        let response;
        if (this.mode == 'edit') {
          response = await this.UpdateConfiguration(
            this.configuration_id,
            this.configuration_data,
          );
        } else {
          response = await this.CreateConfiguration(this.configuration_data);
        }

        if (!response.success) {
          throw { message: response.message };
        }
        notify.success(this.$t('success'));
        this.show_configuration_popup = false;

        this.getDataSetFields(
          this.configuration_data.lookup_dataset_name || '',
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      }
    },
  },
  setup() {
    const doc_type_fields = useDocTypeFieldsStore();
    const { CreateConfiguration, UpdateConfiguration, getDataSetFields } =
      doc_type_fields;
    const {
      lookup_configurations,
      lookup_fields,
      validation_fields,
      validation_fields_sorted,
      show_configuration_popup,
      show_master_data_popup,
    } = storeToRefs(doc_type_fields);

    const master_data_dropdown = useMasterDataDropdownStore();
    const { getMasterDataTypesAndFields } = master_data_dropdown;
    const { master_data_types } = storeToRefs(master_data_dropdown);

    const doc_store = useDocumentStore();
    const { tables_list } = storeToRefs(doc_store);

    return {
      isReadonly: ref(false),
      getDataSetFields,
      CreateConfiguration,
      UpdateConfiguration,
      getMasterDataTypesAndFields,

      tables_list,
      master_data_types,
      validation_fields_sorted,
      show_configuration_popup,
      lookup_configurations,
      validation_fields,
      lookup_fields,
      filtered_master_data_types: ref([]),
      configuration_data: ref({
        doc_type: '',
        lookup_name: '',
        lookup_dataset_name: '',
        match_all: false,
        conflict_handle: 'BEST_SCORE',
        context_type: 'header',
        context_detail: '',
      }),
      conflict_handle_options,
      context_type_options: [
        { label: 'HEADER', value: 'header' },
        { label: 'LINE', value: 'line' },
      ],
    };
  },
});
</script>
