<template>
  <q-card style="min-width: 45vw">
    <q-toolbar class="secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold text-white">{{
          mode == 'edit'
            ? $t('edit_master_data_config')
            : $t('create_master_data_config')
        }}</span>
      </q-toolbar-title>

      <q-btn flat round dense v-close-popup text-color="white" icon="close" />
    </q-toolbar>
    <q-card-section>
      <div class="row">
        <div class="col-sm-6 col-md-6 col-lg-6">
          <q-input
            outlined
            dense
            readonly
            v-model="configuration_data.doc_type"
            :label="$t('document_type')"
            class="q-mr-sm"
          />
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6">
          <q-input
            outlined
            dense
            :readonly="isReadonly"
            v-model="configuration_data.lookup_name"
            :label="$t('lookup_lov_name')"
            :rules="[
              (val) =>
                !val.includes(' ') ||
                $t('no_spaces_error'),
            ]"
          />
        </div>
      </div>
      <div class="row q-pb-md">
        <div class="col-sm-6 col-md-6 col-lg-6">
          <q-select
            v-model="configuration_data.lookup_dataset_name"
            :options="filtered_master_data_types"
            :readonly="isReadonly"
            outlined
            @filter="filterDataSetNames"
            use-input
            :label="$t('lookup_lov_dataset_name')"
            dense
            clearable
            emit-value
            map-options
            class="q-mr-sm"
          >
            <template v-slot:option="scope">
              <q-item v-bind="scope.itemProps">
                <q-item-section>
                  <q-item-label class="text-capitalize">{{
                    scope.opt.label
                  }}</q-item-label>
                </q-item-section>
              </q-item>
            </template>
            <template v-slot:selected-item="scope">
              <q-item-section>
                <q-item-label class="ellipsis text-capitalize">{{
                  scope.opt.label
                }}</q-item-label>
              </q-item-section>
            </template>
          </q-select>
        </div>

        <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
          <q-select
            v-model="configuration_data.context_type"
            :options="context_type_options"
            :readonly="isReadonly"
            outlined
            :label="$t('context_type')"
            dense
            emit-value
            map-options
            class="q-mr-sm"
            @update:model-value="loadOutFieldsData()"
          />
        </div>
      </div>
      <div class="row">
        <div
          class="col-sm-6 col-md-6 col-lg-6 q-pb-md"
          v-if="configuration_data.context_type == 'line'"
        >
          <q-select
            v-model="configuration_data.context_detail"
            :options="tables_list"
            :readonly="isReadonly"
            outlined
            :label="$t('context_detail')"
            dense
            emit-value
            map-options
            @update:model-value="loadOutFieldsData()"
          />
        </div>

        <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
          <q-input
            outlined
            dense
            v-model="configuration_data.lookup_label_field"
            :label="$t('lookup_label_field')"
            class="q-mr-sm"
          />
        </div>
        <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
          <q-input
            outlined
            dense
            v-model="configuration_data.lookup_value_field"
            :label="$t('lookup_value_field')"
            class="q-mr-sm"
          />
        </div>

        <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
          <q-select
            dense
            emit-value
            map-options
            outlined
            v-model="configuration_data.out_field_id"
            :options="out_fields"
            :readonly="isReadonly"
            :label="$t('out_field')"
            class="q-mr-sm"
          />
        </div>
      </div>
    </q-card-section>
    <q-card-actions align="right">
      <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
      <f-btn
        v-if="!isReadonly"
        :label="mode == 'edit' ? $t('save') : $t('create')"
        @click="save"
        class="q-mr-sm"
      />
    </q-card-actions>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import { docFieldsApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import {
  useDocTypeFieldsStore,
  useMasterDataDropdownStore,
  useDocumentStore,
} from 'src/store/main';

export default defineComponent({
    props: {
    configuration_id: {
      type: String,
      default: '',
    },
    configuration: {
      type: Object,
      default: () => ({}),
    },
    mode: {
      type: String,
      default: 'add',
    },
  },
  emits: ['updateLovList'],
  mounted() {
    this.init();
  },
  methods: {
    async init() {
      this.isReadonly = this.mode == 'view' ? true : false;
      this.configuration_data.doc_type = this.$route.params.type.toString();
      await this.getMasterDataTypesAndFields();
      this.filtered_master_data_types = this.master_data_types;
      this.prepareForm();
      this.loadOutFieldsData(false);
    },
    prepareForm() {
      this.configuration_data = {
        doc_type: this.$route.params.type.toString(),
        lookup_name: '',
        context_type: 'header',
        context_detail: '',
        lookup_label_field: '',
        lookup_value_field: '',
        out_field_id: '',
      };

      if (this.configuration_id) {
        this.configuration_data.doc_type = this.configuration.doc_type;
        this.configuration_data.lookup_name = this.configuration.lookup_name;
        this.configuration_data.context_type = this.configuration.context;
        this.configuration_data.out_field_id = this.configuration.out_field_id;
        this.configuration_data.context_detail =
          this.configuration.context_detail;
        this.configuration_data.lookup_label_field =
          this.configuration.lookup_label_field;
        this.configuration_data.lookup_value_field =
          this.configuration.lookup_value_field;
        this.configuration_data.lookup_dataset_name =
          this.configuration.lookup_dataset_name;
      }
    },

    filterDataSetNames(val: string, update: any, abort: any) {
      update(() => {
        const needle = val.toLowerCase();
        this.filtered_master_data_types = this.master_data_types.filter(
           
          (v: any) => v.label.toLowerCase().startsWith(needle),
        );
      });
    },

    validInputs() {
      if (this.configuration_data.lookup_name.includes(' ')) {
        notify.error(i18n.t('no_spaces_error'));
        return false;
      }

      if (!this.configuration_data.lookup_dataset_name) {
        notify.error(i18n.t('fill_all_fields'));
        return false;
      }

      if (this.configuration_data.lookup_name == '') {
        notify.error(i18n.t('fill_all_fields'));
        return false;
      }

      if (this.configuration_data.context_type == 'line') {
        if (!this.configuration_data.context_detail) {
          notify.error(i18n.t('fill_all_fields'));
          return false;
        }
      } else {
        this.configuration_data.context_detail = '';
      }

      if (!this.configuration_data.lookup_value_field) {
        notify.error(i18n.t('fill_all_fields'));
      }

      return true;
    },

    async save() {
      const valid = this.validInputs();
      if (!valid || this.isReadonly) {
        return;
      }

      try {
        let response = await docFieldsApiService.saveConfiguration(
          this.configuration_id,
          this.configuration_data,
        );
        if (!response.success) {
          throw { message: response.message };
        }
        notify.success(this.$t('success'));

        if (this.configuration_id) {
          this.$emit(
            'updateLovList',
            this.configuration_id,
            this.configuration_data,
          );
        } else {
          this.$emit('updateLovList', this.configuration_id, response.data);
        }

        this.getDataSetFields(this.configuration_data.lookup_dataset_name);
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      } finally {
        this.show_lov_configuration_popup = false;
      }
    },
    async loadOutFieldsData(resetOutField = true) {
      if (resetOutField) {
        this.configuration_data.out_field_id = '';
      }
      if (
        this.configuration_data.context_type == 'line' &&
        this.configuration_data.context_detail
      ) {
        await this.loadTableColumnName(this.configuration_data.context_detail);
        this.out_fields = JSON.parse(JSON.stringify(this.tableColumns));
      } else {
        this.out_fields = JSON.parse(
          JSON.stringify(this.all_validation_fields),
        );
      }
    },
  },
  setup() {
    const doc_type_fields = useDocTypeFieldsStore();
    const { getDataSetFields, loadTableColumnName } = doc_type_fields;
    const {
      show_lov_configuration_popup,
      tableColumns,
      all_validation_fields,
    } = storeToRefs(doc_type_fields);

    const master_data_dropdown = useMasterDataDropdownStore();
    const { getMasterDataTypesAndFields } = master_data_dropdown;
    const { master_data_types } = storeToRefs(master_data_dropdown);

    const doc_store = useDocumentStore();
    const { tables_list } = storeToRefs(doc_store);

    return {
      isReadonly: ref(false),
      getDataSetFields,
      loadTableColumnName,
      getMasterDataTypesAndFields,

      tables_list,
      tableColumns,
      master_data_types,
      all_validation_fields,
      show_lov_configuration_popup,
      out_fields: ref([] as any),
      filtered_master_data_types: ref([] as any),
      configuration_data: ref({
        doc_type: '',
        lookup_name: '',
        lookup_dataset_name: '',
        context_type: 'header',
        context_detail: '',
        lookup_label_field: '',
        lookup_value_field: '',
        out_field_id: '',
      } as any),
      context_type_options: [
        { label: 'HEADER', value: 'header' },
        { label: 'LINE', value: 'line' },
      ],
    };
  },
});
</script>
