<template>
  <q-card style="min-width: 58vw">
    <q-toolbar class="secondary-toolbar text-white">
      <q-toolbar-title>
        <span class="text-weight-bold">{{
          mode == 'edit'
            ? $t('edit_master_data_fields')
            : $t('create_master_data_fields')
        }}</span>
      </q-toolbar-title>

      <q-btn flat round dense v-close-popup icon="close" />
    </q-toolbar>
    <form @submit.prevent.stop="save">
      <q-card-section>
        <div class="row">
          <q-select
            :readonly="isReadonly"
            clearable
            outlined
            dense
            use-input
            @filter="filterFieldsEvent"
            v-model="currentData['lookup_field']"
            :options="filteredFieldsList"
            :label="$t('lookup_field')"
            style="width: 49%; margin-right: 1%"
            :required="currentData['lookup_field'] ? false : true"
          >
          </q-select>
          <q-select
            :readonly="isReadonly"
            clearable
            outlined
            dense
            @filter="filterValidationFieldsEvent"
            use-input
            v-model="currentData['validation_field']"
            :options="filteredSourceList"
            :label="$t('validation_field')"
            style="width: 50%"
            :required="currentData['validation_field'] ? false : true"
          >
            <template v-slot:selected-item="scope">
              {{ scope.opt.title }}
            </template>
            <template v-slot:option="scope">
              <q-item v-bind="scope.itemProps">
                <q-item-section>
                  <q-item-label
                    >{{ scope.opt.title }} (
                    {{ scope.opt.field_name }})</q-item-label
                  >
                </q-item-section>
              </q-item>
            </template>
          </q-select>
        </div>
        <div class="row q-py-md">
          <q-select
            :readonly="isReadonly"
            clearable
            outlined
            dense
            @filter="filterValidationFieldsEvent"
            use-input
            v-model="currentData['parent_field']"
            :options="filteredSourceList"
            :label="$t('parent_field')"
            style="width: 49%; margin-right: 1%"
          >
            <template v-slot:option="scope">
              <q-item v-bind="scope.itemProps">
                <q-item-section>
                  <q-item-label
                    >{{ scope.opt.title }} (
                    {{ scope.opt.field_name }})</q-item-label
                  >
                </q-item-section>
              </q-item>
            </template>
            <template v-slot:selected-item="scope">
              {{ scope.opt.title }}
            </template>
          </q-select>
          <q-select
            :readonly="isReadonly"
            clearable
            outlined
            dense
            @filter="filterValidationFieldsEvent"
            use-input
            emit-value
            map-options
            v-model="currentData['search_operator']"
            :options="search_operators"
            :label="$t('search_operator')"
            style="width: 50%"
          >
          </q-select>
        </div>
        <div class="row q-py-md">
          <q-checkbox
            :disable="isReadonly"
            dense
            use-input
            v-model="currentData['auto_trigger']"
            :label="$t('auto_trigger')"
            style="margin-right: 15%"
          ></q-checkbox>
          <q-checkbox
            :disable="isReadonly"
            dense
            use-input
            v-model="currentData['is_searchable']"
            :label="$t('is_searchable')"
          ></q-checkbox>
        </div>
      </q-card-section>
      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          v-if="!isReadonly"
          :label="mode == 'edit' ? $t('save') : $t('create')"
          type="submit"
          class="q-mr-sm"
        />
      </q-card-actions>
    </form>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import {
  useDocTypeFieldsStore,
  useDocMasterDataLookUpStore,
} from 'src/store/main';

export default defineComponent({
  name: 'MasterDataPopUp',
    props: {
    configuration_id: {
      type: String,
      required: true,
    },
    mode: {
      type: String,
      default: 'add',
    },
    field_id: {
      type: String,
      default: '',
    },
    lookup_dataset_name: {
      type: String,
      default: '',
    },
    saveClick: {
      type: Function,
      required: true,
    },
    tableColumnList: {
      type: Array,
      default: () => [],
    },
    isTable: {
      type: Boolean,
      default: false,
    },
  },
  // Your component's JavaScript code goes here
  setup() {
    const doc_type_fields = useDocTypeFieldsStore();
    const { UpdateFields, CreateFields, getFieldsForConfiguration } =
      doc_type_fields;
    const {
      lookup_fields,
      validation_fields,
      validation_fields_sorted,
      all_validation_fields,
      fields_lookup_mapping,
      show_master_data_popup,
    } = storeToRefs(doc_type_fields);
    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const { search_operators } = storeToRefs(doc_ms_data_lookup_store);
    return {
      fields_lookup_mapping,
      lookup_fields,
      UpdateFields,
      CreateFields,
      getFieldsForConfiguration,

      validation_fields_sorted,
      all_validation_fields,
      validation_fields,

      show_master_data_popup,
      currentData: ref({}),
      current_field: ref({}),
      filteredFieldsList: ref([]),
      filteredSourceList: ref([]),
      isReadonly: ref(false),
      docType: ref(''),
      search_operators,
    };
  },
  mounted() {
    this.filteredFieldsList = JSON.parse(
      JSON.stringify(
        this.fields_lookup_mapping[this.lookup_dataset_name].fields,
      ),
    );
    // Set timeout is removed in order to make the fields to be populated on first mocunt
    this.validation_fields.forEach((field) => {
      field.rows.forEach((row: any) => {
        row.forEach((col) => {
          if (this.all_validation_fields.some((f) => f.id === col.id)) {
            return;
          }
          this.all_validation_fields.push(col);
        });
      });
    });

    this.prepareModel();
    this.isReadonly = this.mode == 'view' ? true : false;
  },
  methods: {
    save() {
      try {
        if (this.mode === 'edit') {
          this.UpdateFields(
            this.configuration_id,
            this.field_id,
            this.currentData,
          )
            .then(async (response) => {
              this.show_master_data_popup = false;
              notify.success(
                this.$t('operation_sucessfull'),
              );
              await this.getFieldsForConfiguration(this.configuration_id);
              this.saveClick(this.configuration_id);
            })
            .catch((error: any) => {
              notify.error(error.message);
            });
          return;
        }
        if (this.mode === 'add') {
          this.CreateFields(this.configuration_id, this.currentData)
            .then((response) => {
              this.show_master_data_popup = false;
              notify.success(
                this.$t('operation_sucessfull'),
              );
              this.lookup_fields[this.configuration_id].push(response.data);
              this.saveClick(this.configuration_id);
            })
            .catch((error: any) => {
              notify.error(error.message);
            });
          return;
        }
      } catch (err) {
        logError(err);
      } finally {
        this.show_master_data_popup = false;
      }
    },
    filterFieldsEvent(val, update, abort) {
      const allfields = JSON.parse(
        JSON.stringify(
          this.fields_lookup_mapping[this.lookup_dataset_name].fields,
        ),
      );
      if (!val) {
        update(() => {
          this.filteredFieldsList = allfields;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredFieldsList = allfields.filter(
           
          (v) => v.value.toLowerCase().startsWith(needle),
        );

        logInfo('FILTERED', this.filteredFieldsList);
      });
    },

    filterValidationFieldsEvent(val, update, abort) {
      update(() => {
        const needle = val.toLowerCase();

        let sourceList = this.all_validation_fields;
        if (this.isTable) {
          sourceList = this.tableColumnList;
        }

        this.filteredSourceList = sourceList.filter(
           
          (v) => v.title.toLowerCase().startsWith(needle),
        );
      });
    },

    prepareModel() {
      this.currentData = {
        lookup_field: '',
        validation_field: '',
        parent_field: '',
        auto_trigger: false,
        is_searchable: false,
        search_operator: '',
      };

      if (this.mode == 'add') {
        return;
      }
      this.lookup_fields[this.configuration_id].forEach((field) => {
        if (field.id === this.field_id) {
          this.current_field = field;
          this.currentData.auto_trigger = field.auto_trigger;
          this.currentData.is_searchable = field.is_searchable;
          this.currentData.validation_field = field.matching_field;
          this.currentData.search_operator = field.search_operator;

          let sourceList = this.all_validation_fields;
          if (this.isTable) {
            sourceList = this.tableColumnList;
          }
          const lookup_field = this.fields_lookup_mapping[
            this.lookup_dataset_name
          ].fields.find(
            (f) => f.value.toLowerCase() === field.lookup_field.toLowerCase(),
          );
          const parent_field = sourceList.find(
            (f) => f.id === field.parent_field_id,
          );
          this.currentData.lookup_field = lookup_field;
          this.currentData.parent_field = parent_field;
        }
      });
    },
  },
});
</script>

