<template>
  <div class="row">
    <div class="col-sm-12 col-md-12 col-lg-12 q-pb-md">
      <f-btn
        :label="$t('create_lov_lookup_config')"
        icon="add"
        @click="createConfig"
        class="float-right"
      />
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12">
      <q-list bordered>
        <template
          v-for="(configuration, index) in lov_configurations"
          :key="configuration.id"
        >
          <!-- Your template code goes here -->
          <q-expansion-item
            expand-separator
            header-class="highlighted-back "
            @click="getFields(configuration)"
          >
            <template v-slot:header>
              <span style="margin-top: 3px; text-transform: capitalize">
                {{ configuration.lookup_name.replaceAll('_', ' ') }}
                <q-badge
                  transparent
                  align="middle"
                  v-if="configuration.org_id === DEFAULT"
                  color="orange"
                >
                  {{ $t('default') }}
                </q-badge>
                <q-badge
                  class="q-ml-sm"
                  transparent
                  align="middle"
                  :color="configuration.is_active ? 'green' : 'red'"
                >
                  <template v-if="configuration.is_active">
                    {{ $t('active') }}
                  </template>
                  <template v-else> {{ $t('inactive') }} </template>
                </q-badge>
              </span>
              <q-space />
              <!-- <q-btn rounded flat icon="edit" @click="editConfig(configuration.id)" /> -->
              <q-btn flat dense round @click.stop.prevent icon="more_horiz">
                <q-menu
                  auto-close
                  transition-show="jump-down"
                  transition-hide="jump-up"
                  anchor="bottom middle"
                  self="top middle"
                >
                  <q-list dense style="min-width: 100px">
                    <q-item
                      clickable
                      @click="toggleActivationStatus(configuration)"
                    >
                      <q-item-section>{{
                        configuration.is_active
                          ? $t('deactivate')
                          : $t('activate')
                      }}</q-item-section>
                    </q-item>
                    <q-separator />
                    <q-item
                      clickable
                      @click="prepareDataToDuplicate(configuration)"
                    >
                      <q-item-section>{{ $t('duplicate') }}</q-item-section>
                    </q-item>
                    <q-separator />
                    <q-item clickable @click="editConfig(configuration)">
                      <q-item-section>{{
                        configuration.org_id == DEFAULT
                          ? $t('view')
                          : $t('edit')
                      }}</q-item-section>
                    </q-item>
                    <q-separator />
                    <q-item clickable v-if="configuration.org_id != DEFAULT">
                      <q-item-section
                        @click="
                          deletedConfigConfirmDialog(configuration.id, index as number)
                        "
                      >
                        <span class="text-red-14">{{ $t('delete') }} </span>
                      </q-item-section>
                    </q-item>
                  </q-list>
                </q-menu>
              </q-btn>
            </template>
            <q-card>
              <q-card-actions align="right">
                <f-btn
                  icon="add"
                  :label="$t('create')"
                  @click="createField(configuration)"
                  class="q-mr-sm"
                />
              </q-card-actions>
              <q-card-section :style="'height: auto; min-height: 3vh;'">
                <div class="full-width">
                  <DocBitsTable
                    :rows="(lookup_fields[configuration.id] || []).filter((f: any) => f && Object.keys(f).length > 0)"
                    :columns="lovFieldColumns"
                    row-key="id"
                    :table-id="'lov_fields_' + configuration.id"
                    :features="{
                      sorting: false,
                      filtering: false,
                      selection: false,
                      bulkActions: false,
                      rowActions: true,
                      resizable: false,
                      pagination: false,
                      columnReorder: false,
                      stickyLastColumn: true,
                    }"
                    :row-actions="lovFieldRowActions"
                    no-data-label="no_record_found"
                    flat-style
                    @row-action="(key: string, row: any) => handleLovFieldAction(key, row, configuration)"
                  >
                    <template #body-cell-lookup_field="{ row }">
                      <span class="text-capitalize q-pr-sm">{{ convertLabel(row.lookup_field) }}</span>
                      <q-badge transparent align="middle" v-if="row.org_id === DEFAULT" color="orange">
                        {{ $t('default') }}
                      </q-badge>
                    </template>
                    <template #body-cell-filter_field="{ row }">
                      <span class="text-capitalize">{{ row.matching_field ? row.matching_field.label : row.filter_field_id }}</span>
                    </template>
                    <template #body-cell-is_required="{ row }">
                      <q-icon size="sm" :name="row.is_required ? 'check_circle' : 'cancel'" :color="row.is_required ? 'green' : 'red'" />
                    </template>
                  </DocBitsTable>
                  <!-- <span style="text-transform: capitalize; font-size: 1.05em;">{{ field.lookup_field.replaceAll('_', ' ') }} </span>
                  {{ field.matching_field ? 'MATCHED WITH ' + field.matching_field.title : ''}} -->
                  <!-- <q-badge class="q-ml-md" align="top">{{ field.lookup_field }}</q-badge> -->
                </div>
              </q-card-section>
            </q-card>
          </q-expansion-item>
        </template>
      </q-list>
    </div>
  </div>

  <q-dialog v-model="show_lov_configuration_popup">
    <CreateLovForm
      :mode="current_mode"
      :configuration_id="current_config_id"
      :configuration="current_record"
      @updateLovList="updateLovList"
    />
  </q-dialog>
  <q-dialog v-model="show_lov_master_data_popup">
    <LovFieldPopUp
      :configuration_id="current_config_id"
      :mode="current_mode"
      :field_id="current_field_id"
      :fieldConfig="fieldConfig"
      :lookup_dataset_name="current_record.lookup_dataset_name"
      :tableColumnList="tableColumns"
      :isTable="current_record && current_record.context == 'line'"
      @updateLovFieldList="updateLovFieldList"
    />
  </q-dialog>

  <!-- delete data field modal confirm -->
  <q-dialog v-model="deleteConfirm">
    <q-card class="dialog_style">
      <q-card-section class="flex justify-center items-center">
        <div class="text-h6">
          <q-icon
            name="warning"
            size="2em"
            class="bg-primary icon_circle"
          ></q-icon>
        </div>
      </q-card-section>

      <q-card-section
        class="q-pt-none q-mt-sm text-md text-center text-bold text_style"
      >
        {{ $t('record_confirmation') }}
      </q-card-section>

      <q-card-actions align="right">
        <q-btn :label="$t('cancel')" color="grey-6" v-close-popup />
        <q-btn
          :label="$t('delete')"
          color="red"
          @click="
            deleteField(
              activeItem.config_id,
              activeItem.field_id,
              activeItem.index,
            )
          "
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <!-- delete config modal confirm -->
  <q-dialog v-model="deleteConfigConfirm">
    <q-card class="dialog_style">
      <q-card-section class="flex justify-center items-center">
        <div class="text-h6">
          <q-icon
            name="warning"
            size="2em"
            class="bg-primary icon_circle"
          ></q-icon>
        </div>
      </q-card-section>

      <q-card-section
        class="q-pt-none q-mt-sm text-md text-center text-bold text_style"
      >
        {{ $t('record_confirmation') }}
      </q-card-section>

      <q-card-actions align="right">
        <q-btn :label="$t('cancel')" color="grey-6" v-close-popup />
        <q-btn
          :label="$t('delete')"
          color="red"
          @click="
            deleteConfig(activeConfigItem.config_id, activeConfigItem.index)
          "
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="showDuplicateConfigDlg">
    <q-card class="dialog_style">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title> </q-toolbar-title>

        <q-btn flat round dense v-close-popup text-color="white" icon="close" />
      </q-toolbar>

      <q-card-section>
        <q-input
          outlined
          dense
          v-model="current_record.lookup_name"
          :label="$t('lookup_name')"
        />
      </q-card-section>

      <q-card-actions align="right">
        <q-btn :label="$t('cancel')" color="grey-6" v-close-popup />
        <q-btn :label="$t('done')" color="primary" @click="duplicateConfig()" />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { DEFAULT } from 'src/constants';
import { defineComponent, ref } from 'vue';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { convertLabel } from 'src/utils/ms_utlis';
import { docFieldsApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { useDocTypeFieldsStore } from 'src/store/main';
import LovFieldPopUp from 'src/pages/Settings/Pages/LookUps/LovFieldPopUp.vue';
import CreateLovForm from 'src/pages/Settings/Pages/LookUps/CreateLovForm.vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  el: 'app',
  mixins: [helperMixin],
  components: {
    Loader,
    LovFieldPopUp,
    CreateLovForm,
    DocBitsTable,
  },
  data() {
    return {
      DEFAULT: DEFAULT,
      fieldList: ref([] as any),
      showDuplicateConfigDlg: ref(false),
      lovFieldColumns: [
        { name: 'lookup_field', label: this.$t('lookup_field'), field: 'lookup_field', align: 'left' },
        { name: 'filter_field', label: this.$t('filter_field'), field: 'filter_field_id', align: 'left' },
        { name: 'filter_value', label: this.$t('filter_value'), field: 'filter_value', align: 'left' },
        { name: 'is_required', label: this.$t('required'), field: 'is_required', align: 'center' },
      ] as UnifiedTableColumn[],
      lovFieldRowActions: [
        { key: 'edit', label: 'edit', icon: 'edit' },
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true, show: (row: any) => row.org_id !== DEFAULT },
      ] as RowActionItem[],
    };
  },
  mounted() {
    this.docType = this.$route.params.type as string;
    this.loadConfigurations();
  },
  methods: {
    handleLovFieldAction(key: string, row: any, configuration: any) {
      if (key === 'edit') {
        this.editData(configuration, row);
      } else if (key === 'delete') {
        const fields = this.lookup_fields[configuration.id] || [];
        const index = fields.findIndex((f: any) => f.id === row.id);
        if (index !== -1) this.deletedConfirmDialog(configuration.id, row.id, index);
      }
    },
    async loadConfigurations() {
      await this.getLookUpConfigurations();

      for (const [key, value] of Object.entries(this.lov_configurations)) {
        this.getDataSetFields((value as any).lookup_dataset_name);
      }
    },

    async getLookUpConfigurations() {
      try {
        this.showLoading();
        const response = await docFieldsApiService.getLookupLovConfiguration(
          this.docType,
        );
        this.lov_configurations = response.data;
      } catch (err: any) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    updateLovList(lovConfigId: string, data: any) {
      if (!lovConfigId) {
        this.lov_configurations.push(data);
        return;
      }

      const item = this.lov_configurations.find(
        (item: any) => item.id === lovConfigId,
      );
      if (item) {
        item.doc_type = data.doc_type;
        item.match_all = data.match_all;
        item.lookup_name = data.lookup_name;
        item.conflict_handle = data.conflict_handle;
        item.lookup_dataset_name = data.lookup_dataset_name;
      }
    },

    updateLovFieldList(configuration_id: string, field_id: string, data: any) {
      if (!configuration_id) {
        throw { message: 'CONFIGURATION_ID_MISSING' };
      }

      if (!field_id) {
        this.lookup_fields[configuration_id].push(data);
        this.saveClick(configuration_id);
        return;
      }

      const item = this.lookup_fields[configuration_id].find(
        (item: any) => item.id === field_id,
      );
      if (item) {
        item.is_required = data.is_required;
        item.filter_value = data.filter_value;
        item.lookup_field = data.lookup_field;
        item.filter_field_id = data.filter_field_id;
      }

      this.saveClick(configuration_id);
    },
    saveClick(id: string) {
      this.matchFields(id);
    },
    async deleteConfig(config_id: string, index: number) {
      try {
        const response =
          await docFieldsApiService.deleteLovLookupConfiguration(config_id);
        if (response.success === false) {
          throw { message: response.message };
        }
        this.lov_configurations.splice(index, 1);
        this.deleteConfigConfirm = !this.deleteConfigConfirm;
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      }
    },
    async deleteField(config_id: string, field_id: string, index: number) {
      try {
        const response = await docFieldsApiService.deleteLovConfigField(
          config_id,
          field_id,
        );
        if (!response.success) {
          throw { message: response.message };
        }
        this.lookup_fields[config_id].splice(index, 1);
        this.deleteConfirm = false;
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      }
    },
    createConfig() {
      this.current_mode = 'add';
      this.show_lov_configuration_popup = true;
    },
    async toggleActivationStatus(configuration: any) {
      try {
        this.showLoading();
        const response = await docFieldsApiService.toggleLovActivationStatus(
          configuration.id,
        );
        if (!response.success) {
          throw { message: response.message };
        }
        notify.success(this.$t('success'));
        configuration.is_active = !configuration.is_active;
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    prepareDataToDuplicate(configuration: any) {
      this.showDuplicateConfigDlg = true;
      this.current_record = JSON.parse(JSON.stringify(configuration));
      this.current_record.lookup_name =
        configuration.lookup_name.replaceAll('_', ' ') + ' (copy)';
    },
    async duplicateConfig() {
      try {
        this.showLoading();
        if (!this.current_record.lookup_name) {
          notify.error(this.$t('NAME_MANDATORY'));
          return;
        }

        this.showDuplicateConfigDlg = false;
        const response = await docFieldsApiService.duplicateLovConfig(
          this.current_record.id,
          this.current_record.lookup_name,
        );
        if (!response.success) {
          throw { message: response.message };
        }

        await this.loadConfigurations();
        notify.success(this.$t('success'));
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    editConfig(configuration: any) {
      this.current_config_id = configuration.id;
      this.current_mode = configuration.org_id == DEFAULT ? 'view' : 'edit';
      this.current_record = configuration;
      this.show_lov_configuration_popup = true;
    },
    createField(configuration: any) {
      this.current_config_id = configuration.id;
      this.current_record = configuration;
      this.current_field_id = '';
      this.fieldConfig = {};
      this.current_mode = 'add';
      this.show_lov_master_data_popup = true;
    },
    editData(configuration: any, field: any) {
      this.current_config_id = configuration.id;
      this.current_record = configuration;
      this.current_field_id = field.id;
      this.fieldConfig = field;
      this.current_mode = field.org_id == DEFAULT ? 'view' : 'edit';
      this.show_lov_master_data_popup = true;
    },

    async getFields(configuration: any) {
      const id = configuration.id;
      try {
        if (!this.lookup_fields[id]) {
          await this.getFieldsForConfiguration(id);
        }

        if (configuration.context == 'line' && configuration.context_detail) {
          await this.loadTableColumnName(configuration.context_detail);
          this.prepareDataforColumns(id, configuration.context_detail);
          return;
        }

        this.matchFields(id);
      } catch (err) {
        logError(err);
      }
    },
    async getFieldsForConfiguration(lookup_config_id: string) {
      try {
        // this.processing = true;
        await docFieldsApiService
          .getLovFieldsForConfiguration(lookup_config_id)
          .then((response: any) => {
            this.lookup_fields[lookup_config_id] = response.data;
          });
      } catch (err) {
        logError(err);
      } finally {
        // this.processing = false;
      }
    },
    matchFields(id: string) {
      this.lookup_fields[id].forEach((lookupField: any) => {
        this.all_validation_fields.find((field: any) => {
          if (!this.validation_fields_sorted.includes(field)) {
            this.validation_fields_sorted.push(field);
          }
          if (field.id === lookupField.filter_field_id) {
            lookupField.matching_field = field;
          }
        });
      });
    },
    prepareDataforColumns(id: string, table_name: string) {
      this.lookup_fields[id].forEach((lookupField: any) => {
        for (const columnObj of this.tableColumnList[table_name]) {
          if (columnObj.id === lookupField.filter_field_id) {
            lookupField.matching_field = columnObj;
          }
        }
      });
    },
    // delete config item confirm function
    deletedConfigConfirmDialog(config_id: string, index: number) {
      this.deleteConfigConfirm = true;
      this.activeConfigItem = { config_id: config_id, index: index };
    },
    // delete data field confirm function
    deletedConfirmDialog(config_id: string, field_id: string, index: number) {
      this.deleteConfirm = true;
      this.activeItem = {
        config_id: config_id,
        field_id: field_id,
        index: index,
      };
    },
    convertLabel(label: any) {
      return convertLabel(label);
    },
  },
  setup() {
    const doc_type_fields = useDocTypeFieldsStore();
    const { getDataSetFields, loadTableColumnName } = doc_type_fields;
    const {
      fields,
      fields_lookup_mapping,
      validation_fields,
      all_validation_fields,
      validation_fields_sorted,
      show_lov_master_data_popup,
      show_lov_configuration_popup,
      tableColumnList,
      tableColumns,
    } = storeToRefs(doc_type_fields);

    return {
      fields_lookup_mapping,
      getDataSetFields,
      loadTableColumnName,

      all_validation_fields,
      validation_fields_sorted,
      lov_configurations: ref([] as any),
      show_lov_configuration_popup,
      show_lov_master_data_popup,
      validation_fields,
      lookup_fields: ref([] as any),

      fields,
      current_mode: ref('add'),
      current_config_id: ref(''),
      current_field_id: ref(''),
      fieldConfig: ref({} as any),
      current_record: ref({} as any),
      docType: ref(''),
      deleteConfirm: ref(false),
      deleteConfigConfirm: ref(false),
      activeItem: ref({ config_id: null, field_id: null, index: null } as any),
      activeConfigItem: ref({ config_id: null, index: null } as any),
      tableColumnList,
      tableColumns,
    };
  },
});
</script>

<style scoped>
