<template>
  <q-card-section class="items-center container-wrapper">
    <q-list bordered class="rounded-borders full-width">
      <q-expansion-item
        expand-separator
        header-class="highlighted-back"
        default-opened
      >
        <q-separator />
        <template v-slot:header>
          <q-item-section avatar>
            <q-avatar>
              <Icon icon="mdi:file-document" width="25" height="25" />
            </q-avatar>
          </q-item-section>

          <q-item-section>
            {{ $t('lookup_master_data') }}
          </q-item-section>
        </template>
        <q-card class="page-background">
          <q-card-section>
            <div class="container">
              <FieldMasterData />
            </div>
          </q-card-section>
        </q-card>
      </q-expansion-item>

      <q-expansion-item expand-separator header-class="highlighted-back">
        <q-separator />
        <template v-slot:header>
          <q-item-section avatar>
            <q-avatar>
              <Icon icon="mdi:file-document" width="25" height="25" />
            </q-avatar>
          </q-item-section>

          <q-item-section>
            {{ $t('lov_master_data') }}
          </q-item-section>
        </template>
        <q-card class="page-background">
          <q-card-section>
            <div class="container">
              <LovMasterData />
            </div>
          </q-card-section>
        </q-card>
      </q-expansion-item>
    </q-list>
  </q-card-section>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { docFieldsApiService } from 'src/services';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { useDocumentStore, useDocTypeFieldsStore } from 'src/store/main';
import LovMasterData from 'src/pages/Settings/Pages/LookUps/LovMasterData.vue';
import FieldMasterData from 'src/pages/Settings/Pages/LookUps/LookupMasterData.vue';
export default defineComponent({
  name: 'masfter-data',
  mixins: [displayFieldLabel],
  components: {
    
    LovMasterData,
    FieldMasterData,
  },
  data() {
    return {
      docType: ref(''),
    };
  },
  mounted() {
    this.docType = this.$route.params.type as string;
    this.init();
  },
  methods: {
    async init() {
      this.prepareDocumentTableList(this.docType);
      await this.prepareValidationData();
    },

    async prepareValidationData() {
      if (this.validation_fields.length > 0) {
        return;
      }

      try {
        const data = { doc_type: this.docType };
        const response = await docFieldsApiService.getFieldSettingsByType(data);
        this.validation_fields = response.field_setting;

        this.preapreValidationFields();
      } catch (e: any) {
        notify.error(e);
        throw { message: e };
      }
    },
    preapreValidationFields() {
      this.validation_fields.forEach((field: any) => {
        field.rows.forEach((row: any) => {
          row.forEach((col: any) => {
            if (!this.fields[col.id]) {
              col.label =
                this.getFieldLabel(col) + ' (' + col.field_name + ')';
              col.value = col.id;
              this.fields[col.id] = col;
              this.all_validation_fields.push(col);
            }
          });
        });
      });
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { prepareDocumentTableList } = doc_store;

    const doc_type_fields = useDocTypeFieldsStore();
    const { fields, validation_fields, all_validation_fields } =
      storeToRefs(doc_type_fields);

    return {
      fields,
      validation_fields,
      all_validation_fields,

      prepareDocumentTableList,
    };
  },
});
</script>

