<template>
  <q-card style="min-width: 58vw">
    <q-toolbar class="secondary-toolbar text-white">
      <q-toolbar-title>
        <span class="text-weight-bold">{{
          mode == 'edit'
            ? $t('edit_master_data_fields')
            : $t('create_master_data_fields')
        }}</span>
      </q-toolbar-title>

      <q-btn flat round dense v-close-popup icon="close" />
    </q-toolbar>
    <form @submit.prevent.stop="save">
      <q-card-section>
        <div class="row">
          <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
            <q-select
              :readonly="isReadonly"
              use-input
              clearable
              outlined
              dense
              emit-value
              map-options
              @filter="filterFieldsEvent"
              v-model="currentData['lookup_field']"
              :options="filteredFieldsList"
              :label="$t('lookup_field')"
              class="q-mr-sm"
            >
            </q-select>
          </div>
          <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
            <q-select
              :readonly="isReadonly"
              use-input
              clearable
              outlined
              dense
              emit-value
              map-options
              @filter="filterValidationFieldsEvent"
              v-model="currentData['filter_field_id']"
              :options="filteredSourceList"
              :label="$t('filter_field')"
              option-value="id"
            >
              <template v-slot:selected-item="scope">
                {{ scope.opt.title }}
              </template>
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label
                      >{{ scope.opt.title }} (
                      {{ scope.opt.field_name }})</q-item-label
                    >
                  </q-item-section>
                </q-item>
              </template>
            </q-select>
          </div>

          <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
            <q-input
              outlined
              dense
              :readonly="isReadonly"
              v-model="currentData.filter_value"
              :label="$t('filter_value')"
              class="q-mr-sm"
            />
          </div>
          <div class="col-sm-6 col-md-6 col-lg-6 q-pb-md">
            <q-checkbox
              :disable="isReadonly"
              dense
              use-input
              v-model="currentData['is_required']"
              :label="$t('required')"
            />
          </div>
        </div>
      </q-card-section>
      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          v-if="!isReadonly"
          :label="mode == 'edit' ? $t('save') : $t('create')"
          type="submit"
          class="q-mr-sm"
        />
      </q-card-actions>
    </form>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { docFieldsApiService } from 'src/services';
import {
  useDocTypeFieldsStore,
  useDocMasterDataLookUpStore,
} from 'src/store/main';

export default defineComponent({
  name: 'LovFieldPopUp',
    props: {
    configuration_id: {
      type: String,
      required: true,
    },
    mode: {
      type: String,
      default: 'add',
    },
    field_id: {
      type: String,
      default: '',
    },
    lookup_dataset_name: {
      type: String,
      default: '',
    },
    tableColumnList: {
      type: Array,
      default: () => [],
    },
    isTable: {
      type: Boolean,
      default: false,
    },
    fieldConfig: {
      type: Object,
      default: () => ({}),
    },
  },
  emits: ['updateLovFieldList'],
  mounted() {
    this.init();
  },
  methods: {
    init() {
      this.filteredFieldsList = JSON.parse(
        JSON.stringify(
          this.fields_lookup_mapping[this.lookup_dataset_name].fields,
        ),
      );
      // Set timeout is removed in order to make the fields to be populated on first mocunt
      this.validation_fields.forEach((field: any) => {
        field.rows.forEach((row: any) => {
          row.forEach((col: any) => {
            if (this.all_validation_fields.some((f: any) => f.id === col.id)) {
              return;
            }
            this.all_validation_fields.push(col);
          });
        });
      });

      this.prepareModel();

      this.filteredSourceList = this.prepareFilteredSourceList();
      this.isReadonly = this.mode == 'view' ? true : false;
    },
    async save() {
      try {
        let dataToUpdate = {};
        const response = await docFieldsApiService.saveLovFieldConfig(
          this.configuration_id,
          this.field_id,
          this.currentData,
        );

        if (this.mode === 'edit') {
          dataToUpdate = this.currentData;
        } else {
          dataToUpdate = response.data;
        }

        this.show_lov_master_data_popup = false;
        notify.success(this.$t('operation_sucessfull'));

        this.$emit(
          'updateLovFieldList',
          this.configuration_id,
          this.field_id,
          dataToUpdate,
        );
      } catch (e: any) {
        notify.error(e.message);
      }
    },

    filterFieldsEvent(val: any, update: any, abort: any) {
      const allfields = JSON.parse(
        JSON.stringify(
          this.fields_lookup_mapping[this.lookup_dataset_name].fields,
        ),
      );
      if (!val) {
        update(() => {
          this.filteredFieldsList = allfields;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredFieldsList = allfields.filter(
           
          (v: any) => v.value.toLowerCase().startsWith(needle),
        );
      });
    },

    filterValidationFieldsEvent(val: any, update: any, abort: any) {
      update(() => {
        const needle = val.toLowerCase();

        let sourceList = this.prepareFilteredSourceList();

        this.filteredSourceList = sourceList.filter(
           
          (v: any) => v.title.toLowerCase().startsWith(needle),
        );
      });
    },
    prepareFilteredSourceList(): any {
      let sourceList = this.all_validation_fields;
      if (this.isTable) {
        sourceList = this.tableColumnList;
      }

      return sourceList;
    },

    prepareModel() {
      this.currentData = {
        lookup_field: '',
        filter_value: '',
        is_required: false,
        filter_field_id: '',
      };

      if (this.mode == 'add') {
        return;
      }
      this.currentData = JSON.parse(JSON.stringify(this.fieldConfig));
    },
  },
  setup() {
    const doc_type_fields = useDocTypeFieldsStore();
    const {
      validation_fields,
      all_validation_fields,
      fields_lookup_mapping,
      show_lov_master_data_popup,
    } = storeToRefs(doc_type_fields);
    const doc_ms_data_lookup_store = useDocMasterDataLookUpStore();
    const { search_operators } = storeToRefs(doc_ms_data_lookup_store);
    return {
      fields_lookup_mapping,
      all_validation_fields,
      validation_fields,

      show_lov_master_data_popup,
      currentData: ref({} as any),
      current_field: ref({} as any),
      filteredFieldsList: ref([] as any),
      filteredSourceList: ref([] as any),
      isReadonly: ref(false),
      docType: ref(''),
      search_operators,
    };
  },
});
</script>

