<template>
  <div class="row">
    <div class="col-sm-12 col-md-12 col-lg-12 q-pb-md">
      <f-btn
        :label="$t('create_lookup_config')"
        icon="add"
        @click="createConfig"
        class="float-right"
      />
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12">
      <q-list bordered>
        <template
          v-for="(configuration, index) in lookup_configurations"
          :key="configuration.id"
        >
          <!-- Your template code goes here -->
          <q-expansion-item
            expand-separator
            header-class="highlighted-back "
            @click="getFields(configuration)"
          >
            <template v-slot:header>
              <span style="margin-top: 3px; text-transform: capitalize">
                {{ configuration.lookup_name.replaceAll('_', ' ') }}
                <q-badge
                  transparent
                  align="middle"
                  v-if="configuration.org_id === DEFAULT"
                  color="orange"
                >
                  {{ $t('default') }}
                </q-badge>
                <q-badge
                  class="q-ml-sm"
                  transparent
                  align="middle"
                  :color="configuration.is_active ? 'green' : 'red'"
                >
                  <template v-if="configuration.is_active">
                    {{ $t('active') }}
                  </template>
                  <template v-else> {{ $t('inactive') }} </template>
                </q-badge>
              </span>
              <q-space />
              <!-- <q-btn rounded flat icon="edit" @click="editConfig(configuration.id)" /> -->
              <q-btn flat dense round @click.stop.prevent icon="more_horiz">
                <q-menu
                  auto-close
                  transition-show="jump-down"
                  transition-hide="jump-up"
                  anchor="bottom middle"
                  self="top middle"
                >
                  <q-list dense style="min-width: 100px">
                    <q-item
                      clickable
                      @click="toggleActivationStatus(configuration)"
                    >
                      <q-item-section>{{
                        configuration.is_active
                          ? $t('deactivate')
                          : $t('activate')
                      }}</q-item-section>
                    </q-item>
                    <q-separator />
                    <q-item
                      clickable
                      @click="prepareDataToDuplicate(configuration)"
                    >
                      <q-item-section>{{ $t('duplicate') }}</q-item-section>
                    </q-item>
                    <q-separator />
                    <q-item clickable @click="editConfig(configuration)">
                      <q-item-section>{{
                        configuration.org_id == DEFAULT
                          ? $t('view')
                          : $t('edit')
                      }}</q-item-section>
                    </q-item>
                    <q-separator />
                    <q-item clickable v-if="configuration.org_id != DEFAULT">
                      <q-item-section
                        @click="
                          DeletedConfigConfirmDialog(configuration.id, index)
                        "
                      >
                        <span class="text-red-14">{{ $t('delete') }} </span>
                      </q-item-section>
                    </q-item>
                  </q-list>
                </q-menu>
              </q-btn>
            </template>
            <q-card>
              <q-card-actions align="right">
                <f-btn
                  icon="add"
                  :label="$t('create')"
                  @click="createField(configuration)"
                  class="q-mr-sm"
                />
              </q-card-actions>
              <q-card-section :style="'height: auto; min-height: 3vh;'">
                <div class="full-width">
                  <DocBitsTable
                    :rows="(lookup_fields[configuration.id] || []).filter((f) => f && Object.keys(f).length > 0)"
                    :columns="lookupFieldColumns"
                    row-key="id"
                    :table-id="'lookup_fields_' + configuration.id"
                    :features="{
                      sorting: false,
                      filtering: false,
                      selection: false,
                      bulkActions: false,
                      rowActions: true,
                      resizable: false,
                      pagination: false,
                      columnReorder: false,
                      stickyLastColumn: true,
                    }"
                    :row-actions="lookupFieldRowActions"
                    no-data-label="no_record_found"
                    flat-style
                    @row-action="(payload) => handleLookupFieldAction(payload, configuration)"
                  >
                    <template #body-cell-lookup_field="{ row }">
                      <span class="text-capitalize q-pr-sm">{{ convertLabel(row.lookup_field) }}</span>
                      <q-badge transparent align="middle" v-if="row.org_id === DEFAULT" color="orange">
                        {{ $t('default') }}
                      </q-badge>
                    </template>
                    <template #body-cell-validation_field="{ row }">
                      <span v-if="row.matching_field">{{ row.matching_field.title }} ({{ row.matching_field.field_name }})</span>
                      <span v-else>{{ $t('No Match') }}</span>
                    </template>
                    <template #body-cell-parent_field="{ row }">
                      <span class="text-capitalize">{{ row.parent_field_id ? row.parent_field.title + '(' + row.parent_field.field_name + ')' : $t('none') }}</span>
                    </template>
                    <template #body-cell-is_searchable="{ row }">
                      <q-icon size="sm" :name="row.is_searchable ? 'check_circle' : 'cancel'" :color="row.is_searchable ? 'green' : 'red'" />
                    </template>
                    <template #body-cell-auto_trigger="{ row }">
                      <q-icon size="sm" :name="row.auto_trigger ? 'check_circle' : 'cancel'" :color="row.auto_trigger ? 'green' : 'red'" />
                    </template>
                  </DocBitsTable>
                  <!-- <span style="text-transform: capitalize; font-size: 1.05em;">{{ field.lookup_field.replaceAll('_', ' ') }} </span>
                  {{ field.matching_field ? 'MATCHED WITH ' + field.matching_field.title : ''}} -->
                  <!-- <q-badge class="q-ml-md" align="top">{{ field.lookup_field }}</q-badge> -->
                </div>
              </q-card-section>
            </q-card>
          </q-expansion-item>
        </template>
      </q-list>
    </div>
  </div>

  <q-dialog v-model="show_configuration_popup">
    <LookupConfigurationPopUp
      :mode="current_mode"
      :configuration_id="current_config_id"
    />
  </q-dialog>
  <q-dialog v-model="show_master_data_popup">
    <FieldPopUp
      :configuration_id="current_config_id"
      :mode="current_mode"
      :field_id="current_field_id"
      :lookup_dataset_name="current_record.lookup_dataset_name"
      :tableColumnList="tableColumns"
      :isTable="current_record && current_record.context == 'line'"
      :saveClick="saveClick"
    />
  </q-dialog>

  <!-- delete data field modal confirm -->
  <q-dialog v-model="deleteConfirm">
    <q-card class="dialog_style">
      <q-card-section class="flex justify-center items-center">
        <div class="text-h6">
          <q-icon
            name="warning"
            size="2em"
            class="bg-primary icon_circle"
          ></q-icon>
        </div>
      </q-card-section>

      <q-card-section
        class="q-pt-none q-mt-sm text-md text-center text-bold text_style"
      >
        {{ $t('record_confirmation') }}
      </q-card-section>

      <q-card-actions align="right">
        <q-btn :label="$t('cancel')" color="grey-6" v-close-popup />
        <q-btn
          :label="$t('delete')"
          color="red"
          @click="
            deleteEvent(
              activeItem.config_id,
              activeItem.field_id,
              activeItem.index,
            )
          "
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <!-- delete config modal confirm -->
  <q-dialog v-model="deleteConfigConfirm">
    <q-card class="dialog_style">
      <q-card-section class="flex justify-center items-center">
        <div class="text-h6">
          <q-icon
            name="warning"
            size="2em"
            class="bg-primary icon_circle"
          ></q-icon>
        </div>
      </q-card-section>

      <q-card-section
        class="q-pt-none q-mt-sm text-md text-center text-bold text_style"
      >
        {{ $t('record_confirmation') }}
      </q-card-section>

      <q-card-actions align="right">
        <q-btn :label="$t('cancel')" color="grey-6" v-close-popup />
        <q-btn
          :label="$t('delete')"
          color="red"
          @click="
            deleteConfig(activeConfigItem.config_id, activeConfigItem.index)
          "
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="showDuplicateConfigDlg">
    <q-card class="dialog_style">
      <q-toolbar class="secondary-toolbar">
        <q-toolbar-title> </q-toolbar-title>

        <q-btn flat round dense v-close-popup text-color="white" icon="close" />
      </q-toolbar>

      <q-card-section>
        <q-input
          outlined
          dense
          v-model="current_record.lookup_name"
          :label="$t('lookup_name')"
        />
      </q-card-section>

      <q-card-actions align="right">
        <q-btn :label="$t('cancel')" color="grey-6" v-close-popup />
        <q-btn :label="$t('done')" color="primary" @click="duplicateConfig()" />
      </q-card-actions>
    </q-card>
  </q-dialog>
  <Loader />
</template>

<script>
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { DEFAULT } from 'src/constants';
import { defineComponent, ref } from 'vue';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { convertLabel } from 'src/utils/ms_utlis';
import { ApiExceptions } from 'src/exceptions/index';
import { useDocTypeFieldsStore } from 'src/store/main';
import { docFieldsApiService, documentTypeApiService } from 'src/services';
import FieldPopUp from 'src/pages/Settings/Components/DocTypes/FieldPopUp.vue';
import LookupConfigurationPopUp from 'src/pages/Settings/Components/DocTypes/CreateLookupPopUp.vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';

export default defineComponent({
  el: 'app',
  mixins: [helperMixin],
  components: {
    Loader,
    FieldPopUp,
    LookupConfigurationPopUp,
    DocBitsTable,
  },
  data() {
    return {
      DEFAULT: DEFAULT,
      showDuplicateConfigDlg: ref(false),
      lookupFieldRowActions: [
        { key: 'edit', label: 'edit', icon: 'edit' },
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative', separator: true, show: (row) => row.org_id !== DEFAULT },
      ],
    };
  },
  computed: {
    lookupFieldColumns() {
      return [
        { name: 'lookup_field', label: this.$t('lookup_field'), field: 'lookup_field', align: 'left' },
        { name: 'validation_field', label: this.$t('validation_field'), field: 'field_id', align: 'left' },
        { name: 'parent_field', label: this.$t('parent_field'), field: 'parent_field_id', align: 'left' },
        { name: 'is_searchable', label: this.$t('is_searchable'), field: 'is_searchable', align: 'center' },
        { name: 'auto_trigger', label: this.$t('auto_trigger'), field: 'auto_trigger', align: 'center' },
      ];
    },
  },
  // Your component options go here
  mounted() {
    this.loadConfigurations();
  },
  setup() {
    const doc_type_fields = useDocTypeFieldsStore();
    const {
      getLookUpConfigurations,
      getFieldsForConfiguration,
      deleteField,
      deleteLookupConfiguration,
      getDataSetFields,
    } = doc_type_fields;
    const {
      lookup_configurations,
      fields_lookup_mapping,
      lookup_fields,
      validation_fields,
      validation_fields_sorted,
      show_configuration_popup,
      show_master_data_popup,
      all_validation_fields,
    } = storeToRefs(doc_type_fields);
    return {
      deleteField,
      getDataSetFields,
      getLookUpConfigurations,
      getFieldsForConfiguration,
      deleteLookupConfiguration,

      validation_fields_sorted,
      show_configuration_popup,
      show_master_data_popup,
      all_validation_fields,
      fields_lookup_mapping,
      lookup_configurations,
      validation_fields,
      lookup_fields,

      current_mode: ref('add'),
      current_config_id: ref(''),
      current_field_id: ref(''),
      current_record: ref({}),
      docType: ref(''),
      deleteConfirm: ref(false),
      deleteConfigConfirm: ref(false),
      activeItem: ref({ config_id: null, field_id: null, index: null }),
      activeConfigItem: ref({ config_id: null, index: null }),
      tableColumnList: ref({}),
      tableColumns: ref([]),
    };
  },
  methods: {
    handleLookupFieldAction(payload, configuration) {
      const { action, row } = payload;
      if (action === 'edit') {
        this.editData(configuration, row);
      } else if (action === 'delete') {
        const fields = this.lookup_fields[configuration.id] || [];
        const index = fields.findIndex((f) => f.id === row.id);
        if (index !== -1) this.DeletedConfirmDialog(configuration.id, row.id, index);
      }
    },
    async loadConfigurations() {
      this.docType = this.$route.params.type.toString();
      await this.getLookUpConfigurations(this.docType);

      for (const [key, value] of Object.entries(this.lookup_configurations)) {
        this.getDataSetFields(value.lookup_dataset_name);
      }
    },
    saveClick(id) {
      this.matchFields(id);
    },
    async deleteConfig(config_id, index) {
      try {
        const response = await this.deleteLookupConfiguration(config_id);
        if (response.success === false) {
          throw { message: response.message };
        }
        this.lookup_configurations.splice(index, 1);
        this.deleteConfigConfirm = !this.deleteConfigConfirm;
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      }
    },
    async deleteEvent(config_id, field_id, index) {
      try {
        const response = await this.deleteField(config_id, field_id);
        if (!response.success) {
          throw { message: response.message };
        }
        this.lookup_fields[config_id].splice(index, 1);
        this.deleteConfirm = !this.deleteConfirm;
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      }
    },
    createConfig() {
      this.current_mode = 'add';
      this.show_configuration_popup = true;
    },
    async toggleActivationStatus(configuration) {
      try {
        this.showLoading();
        const response = await docFieldsApiService.toggleActivationStatus(
          configuration.id,
        );
        if (!response.success) {
          throw { message: response.message };
        }
        notify.success(this.$t('success'));
        configuration.is_active = !configuration.is_active;
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    prepareDataToDuplicate(configuration) {
      this.showDuplicateConfigDlg = true;
      this.current_record = JSON.parse(JSON.stringify(configuration));
      this.current_record.lookup_name =
        configuration.lookup_name.replaceAll('_', ' ') + ' (copy)';
    },
    async duplicateConfig() {
      try {
        this.showLoading();
        if (!this.current_record.lookup_name) {
          notify.error(this.$t('NAME_MANDATORY'));
          return;
        }

        for (let config of this.lookup_configurations) {
          if (
            config.lookup_name.toLowerCase() ==
            this.current_record.lookup_name.toLowerCase().trim()
          ) {
            notify.error(
              this.$t('LOOKUP_NAME_ALREADY_EXISTS'),
            );
            return;
          }
        }

        this.showDuplicateConfigDlg = false;
        const response = await docFieldsApiService.duplicateConfig(
          this.current_record.id,
          this.current_record.lookup_name,
        );
        if (!response.success) {
          throw { message: response.message };
        }

        await this.loadConfigurations();
        notify.success(this.$t('success'));
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    editConfig(configuration) {
      this.current_config_id = configuration.id;
      this.current_mode = configuration.org_id == DEFAULT ? 'view' : 'edit';
      this.current_record = configuration;
      this.show_configuration_popup = true;
    },
    createField(configuration) {
      this.current_config_id = configuration.id;
      this.current_record = configuration;
      this.current_field_id = '';
      this.current_mode = 'add';
      this.show_master_data_popup = true;
      if (configuration.context == 'line' && configuration.context_detail) {
        this.loadTableColumnName(configuration.context_detail);
      }
    },
    editData(configuration, field) {
      this.current_config_id = configuration.id;
      this.current_record = configuration;
      this.current_field_id = field.id;
      this.current_mode = field.org_id == DEFAULT ? 'view' : 'edit';
      this.show_master_data_popup = true;
      if (
        configuration.context_type == 'line' &&
        configuration.context_detail
      ) {
        this.loadTableColumnName(configuration.context_detail);
      }
    },
    async loadTableColumnName(table_name) {
      try {
        if (
          Object.keys(this.tableColumnList).length > 0 &&
          this.tableColumnList[table_name].length > 0
        ) {
          this.tableColumns = this.tableColumnList[table_name];
          return;
        }

        this.tableColumnList[table_name] = [];
        const response =
          await documentTypeApiService.getDocumentTableColumns(table_name);

        if (response.data && !response.success) {
          throw response;
        }

        for (const columnObj of response.data) {
          this.tableColumnList[table_name].push({
            value: columnObj.column_name,
            label: this.$t(columnObj.column_name),
            title: this.$t(columnObj.column_name),
            field_name: columnObj.column_name,
            id: columnObj.id,
          });
        }
        this.tableColumns = this.tableColumnList[table_name];
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
        logError(err);
      }
    },
    async getFields(configuration) {
      const id = configuration.id;
      try {
        if (this.lookup_fields[id]) {
          return;
        }
        await this.getFieldsForConfiguration(id);

        if (configuration.context == 'line' && configuration.context_detail) {
          await this.loadTableColumnName(configuration.context_detail);
          this.prepareDataforColumns(id, configuration.context_detail);
          return;
        }

        this.matchFields(id);
      } catch (err) {
        logError(err);
      }
    },
    matchFields(id) {
      this.lookup_fields[id].forEach((lookupField) => {
        this.all_validation_fields.find((field) => {
          if (!this.validation_fields_sorted.includes(field)) {
            this.validation_fields_sorted.push(field);
          }

          if (field.id === lookupField.field_id) {
            lookupField.matching_field = field;
          }
          if (field.id === lookupField.parent_field_id) {
            lookupField.parent_field = field;
          }
        });
      });
    },
    prepareDataforColumns(id, table_name) {
      this.lookup_fields[id].forEach((lookupField) => {
        for (const columnObj of this.tableColumnList[table_name]) {
          if (columnObj.id === lookupField.field_id) {
            lookupField.matching_field = columnObj;
          }
          if (columnObj.id === lookupField.parent_field_id) {
            lookupField.parent_field = columnObj;
          }
        }
      });
    },
    // delete config item confirm function
    DeletedConfigConfirmDialog(config_id, index) {
      this.deleteConfigConfirm = !this.deleteConfigConfirm;
      this.activeConfigItem = { config_id: config_id, index: index };
    },
    // delete data field confirm function
    DeletedConfirmDialog(config_id, field_id, index) {
      this.deleteConfirm = !this.deleteConfirm;
      this.activeItem = {
        config_id: config_id,
        field_id: field_id,
        index: index,
      };
    },
    convertLabel(label) {
      return convertLabel(label);
    },
  },
});
</script>

<style scoped>
.lookup-real-name {
  font-size: 0.95em;
}

.dialog_style {
  width: 500px;
}

.icon_circle {
  border-radius: 50%;
  padding: 10px;
}
.field-master-container {
  height: calc(100vh - 167px);
  overflow-y: auto;
}
.text_style {
  color: gray;
}
/* Your component styles go here */
</style>
